import type { Guide, SiteKey } from "./types";

const updatedAt = "August 11, 2026";

type Pilot3Spec = {
  site: Extract<SiteKey, "network" | "smarthome" | "homeoffice" | "baby" | "pet">;
  familySlug: string;
  slug: string;
  title: string;
  dek: string;
  category: string;
  imageAlt: string;
  searchQuestion: string;
  quickAnswer: string;
  independentDemand: string;
  distinctFrom: string;
  benchmark: string;
  tableTitle: string;
  rows: Array<[string, string, string]>;
  editorialMethod: string[];
  communityTitle: string;
  communityQuery: string;
  sections: Array<[string, string]>;
  sources: Array<{ name: string; url: string; note: string }>;
  asin: string;
  relatedGuides: string[];
  relatedRoundups?: string[];
};

function pilot3Guide(spec: Pilot3Spec): Guide {
  return {
    site: spec.site,
    slug: spec.slug,
    familySlug: spec.familySlug,
    title: spec.title,
    dek: spec.dek,
    category: spec.category,
    publicationStatus: "published",
    updatedAt,
    familyRole: "buying",
    image: `/images/affiliate/broad3-${spec.site}-${spec.familySlug}.webp`,
    imageAlt: spec.imageAlt,
    searchQuestion: spec.searchQuestion,
    quickAnswer: spec.quickAnswer,
    governance: {
      decision: "rewrite",
      independentDemand: spec.independentDemand,
      distinctFrom: spec.distinctFrom,
      benchmark: spec.benchmark,
    },
    comparisonTable: {
      title: spec.tableTitle,
      columns: ["Record before ordering", "Why it changes the decision"],
      rows: spec.rows.map(([label, record, why]) => ({ label, values: [record, why] })),
    },
    editorialMethod: spec.editorialMethod,
    communityEvidence: [{
      sourceName: "Reddit community search",
      title: spec.communityTitle,
      url: `https://www.reddit.com/search/?q=${encodeURIComponent(spec.communityQuery)}`,
      note: "Used to locate real owner questions and failure reports that shape the inspection checklist. Anecdotes are not presented as measured product tests or copied as endorsements.",
    }],
    sections: spec.sections.map(([heading, body]) => ({ heading, body })),
    sources: [
      ...spec.sources,
      { name: `Amazon ASIN ${spec.asin}`, url: `https://www.amazon.com/dp/${spec.asin}`, note: "Exact US checkout identity for this draft. Recheck the selected variation, seller, included parts, live availability, and any recall notice on release day." },
    ],
    relatedGuides: spec.relatedGuides,
    relatedRoundups: spec.relatedRoundups ?? [],
  };
}

